SELECT ST_XMin(ST_3DMakeBox(ST_PointZ($1, $2, $3), ST_PointZ($4, $5, $6))) AS xmin, ST_YMin(ST_3DMakeBox(ST_PointZ($1, $2, $3), ST_PointZ($4, $5, $6))) AS ymin, ST_ZMin(ST_3DMakeBox(ST_PointZ($1, $2, $3), ST_PointZ($4, $5, $6))) AS zmin, ST_XMax(ST_3DMakeBox(ST_PointZ($1, $2, $3), ST_PointZ($4, $5, $6))) AS xmax, ST_YMax(ST_3DMakeBox(ST_PointZ($1, $2, $3), ST_PointZ($4, $5, $6))) AS ymax, ST_ZMax(ST_3DMakeBox(ST_PointZ($1, $2, $3), ST_PointZ($4, $5, $6))) AS zmax
